// the page side of webrtc-bridge: the real RTCPeerConnection lives here, the vault worker drives it with messages
// (see webrtc-bridge.js). with transfer: true the data channel is transferred to the worker, so the data goes from the
// worker straight to the other browser. otherwise it stays here and every message is forwarded
module.exports = serve_webrtc

const { make_tx } = require('iframe-runtime')
const { split, make_joiner } = require('./pieces')

// transfer only works into a dedicated worker. chrome 156 and firefox 160 drop a data channel sent to a SharedWorker
// (a messageerror in the worker, no error in the page), so the SharedWorker vault keeps forwarding
function serve_webrtc (worker, { transfer = false } = {}) {
  const peers = new Map() // id -> { rtc, channel, on_piece }
  const ops = { create, create_channel, send, close_channel, close, create_offer, create_answer, set_local_description, set_remote_description, add_ice_candidate }
  const tx = make_tx('webrtc-page')
  worker.addEventListener('message', on_message)

  async function on_message (event) {
    const msg = event.data
    if (msg?.type === 'rtc-page' && !document.title.startsWith('📡')) document.title = '📡 ' + document.title // this tab holds the webrtc connections of the worker
    if (msg?.type !== 'rtc') return
    const { id, op, args } = msg.data
    const reply = { to: 'webrtc', type: 'rtc-reply', refs: { cause: msg.head } }
    try {
      worker.postMessage(tx({ ...reply, data: { value: await ops[op](id, ...args) } }))
    } catch (err) {
      worker.postMessage(tx({ ...reply, data: { error: err.message } }))
    }
  }
  function create (id, options) {
    const rtc = new RTCPeerConnection(options)
    rtc.onicecandidate = e => send_event(id, 'icecandidate', e.candidate && e.candidate.toJSON())
    peers.set(id, { rtc, channel: null, on_piece: make_joiner(data => send_event(id, 'message', data, peers.get(id)?.channel?.readyState || 'closed')) })
  }
  function create_channel (id, label, options) {
    const peer = peers.get(id)
    const channel = peer.rtc.createDataChannel(label, options)
    if (transfer && transfer_channel(id, channel)) return
    peer.channel = channel
    channel.binaryType = 'arraybuffer'
    for (const type of ['open', 'message', 'error', 'close']) channel.addEventListener(type, e => on_channel_event(id, type, e))
  }
  // a channel can only be transferred before its used, so right after its made. true if the worker has it now
  function transfer_channel (id, channel) {
    try {
      worker.postMessage(tx({ to: 'webrtc', type: 'rtc-channel', data: { id, channel } }), [channel])
      return true
    } catch (err) {
      return false // this browser cant transfer data channels, the page forwards then
    }
  }
  function on_channel_event (id, type, e) {
    const peer = peers.get(id)
    if (type === 'message') return peer?.on_piece(new Uint8Array(e.data))
    send_event(id, type, null, peer?.channel?.readyState || 'closed')
    if (type === 'close') peers.delete(id)
  }
  function send_event (id, type, data, ready_state) { worker.postMessage(tx({ to: 'webrtc', type: 'rtc-event', data: { id, type, data, ready_state } })) }
  function send (id, data) {
    const channel = peers.get(id)?.channel
    for (const piece of split(data)) channel?.send(piece)
  }
  function close_channel (id) { peers.get(id)?.channel?.close() }
  function close (id) {
    peers.get(id)?.rtc.close()
    if (!peers.get(id)?.channel) peers.delete(id) // a transferred channel closes in the worker, nothing left here
  }
  async function create_offer (id) { return plain(await peers.get(id).rtc.createOffer()) }
  async function create_answer (id) { return plain(await peers.get(id).rtc.createAnswer()) }
  async function set_local_description (id, description) {
    const rtc = peers.get(id).rtc
    await rtc.setLocalDescription(description)
    return plain(rtc.localDescription)
  }
  function set_remote_description (id, description) { return peers.get(id).rtc.setRemoteDescription(description) }
  function add_ice_candidate (id, candidate) { return peers.get(id).rtc.addIceCandidate(candidate) }
}

// descriptions can be browser objects that postMessage cant copy, the worker only needs { type, sdp }
function plain (description) { return description && { type: description.type, sdp: description.sdp } }
